def longest_subarray_at_most_k(arr, k):
    n = len(arr)
    best = 0
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += arr[j]
            if total <= k:
                best = max(best, j - i + 1)
            else:
                break
    return best

