def min_subarray_len(s, nums):
    n = len(nums)
    best = float('inf')
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += nums[j]
            if total >= s:
                best = min(best, j - i + 1)
                break
    return 0 if best == float('inf') else best

