def find_max_len(nums):
    best = 0
    for i in range(len(nums)):
        zeros = 0
        ones = 0
        for j in range(i, len(nums)):
            if nums[j] == 0:
                zeros += 1
            else:
                ones += 1
            if zeros == ones:
                best = max(best, j - i + 1)
    return best

