def find_max_len(nums):
    best = 0
    balance = 0
    first_seen = {0: -1}
    for i, num in enumerate(nums):
        balance += 1 if num == 1 else -1
        if balance in first_seen:
            best = max(best, i - first_seen[balance])
        else:
            first_seen[balance] = i
    return best

