def alert_latency_spike(latencies, k, threshold):
    if len(latencies) < k or k <= 0:
        return False
    curr_sum = sum(latencies[:k])
    if curr_sum / k > threshold:
        return True
    for i in range(k, len(latencies)):
        curr_sum += latencies[i] - latencies[i - k]
        if curr_sum / k > threshold:
            return True
    return False
